import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  color,
  mix,
  smoothstep,
  distance,
  dot,
  sin,
  fract,
  texture,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, PointLight, Texture, Color } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'primary-cta-decor';

  const content = new Group();
  root.add(content);

  // ---- Panel geometry (thin extruded card, non-interactive decorative CTA panel) ----
  const width = 2.4;
  const height = 0.66;
  const depth = 0.1;
  const geometry = new BoxGeometry(width, height, depth, 1, 1, 1);

  // ---- Decorative texture node (loaded async, blended into engineered gradient) ----
  const placeholderTex = new Texture();
  const texNode = texture(placeholderTex);

  const uvNode = uv();
  const inkColor = color(colors.ink);
  const surfaceColor = color(colors.surface);
  const accentColor = color(colors.accent);

  // vertical engineered gradient
  const gradient = mix(surfaceColor, inkColor, uvNode.y);

  // subtle center accent glow (kept well under 10% coverage via tight falloff)
  const centerDist = distance(uvNode, vec2(0.5, 0.5)).mul(2.0);
  const centerGlow = smoothstep(0.75, 0.0, centerDist).mul(0.12);
  const withAccent = mix(gradient, accentColor, centerGlow);

  // subtle static grain (no time dependency -> static composition)
  const grainHash = fract(
    sin(dot(uvNode.mul(4331.17), vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grainAmount = grainHash.sub(0.5).mul(0.035);
  const withGrain = withAccent.add(vec3(grainAmount, grainAmount, grainAmount));

  // decorative orb texture overlay, low-opacity blend
  const finalColor = mix(withGrain, texNode.rgb, texNode.a.mul(0.35));

  const material = new MeshPhysicalNodeMaterial({
    roughness: 0.56,
    metalness: 0.32,
    clearcoat: 0.15,
    clearcoatRoughness: 0.4,
  });
  material.colorNode = finalColor;
  material.opacity = 0;
  material.transparent = true;

  const panel = new Mesh(geometry, material);
  content.add(panel);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texNode.value = tex;
    }).catch(() => {});
  }

  // ---- Rim / accent light, node-local per doctrine (scene only supplies ambient+key) ----
  const rimLight = new PointLight(new Color(colors.accent), 0.7, 4, 2);
  rimLight.position.set(-1.1, 0.4, 0.9);
  content.add(rimLight);

  // ---- Grounded contact shadow ----
  const shadowRadius = Math.max(width, height) * 1.3;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 1.1);
  const shadowMat = new MeshPhysicalNodeMaterial({ roughness: 1.0, metalness: 0.0 });
  shadowMat.transparent = true;
  const sUv = uv();
  const sDist = distance(sUv, vec2(0.5, 0.5));
  const sAlpha = smoothstep(0.5, 0.0, sDist).mul(0.5);
  shadowMat.colorNode = vec3(0.01, 0.01, 0.015);
  shadowMat.opacityNode = sAlpha;
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -height * 0.7, -depth * 0.5);
  content.add(shadowMesh);

  // ---- Motion: weighted-settle entrance + single slow idle breathing ----
  content.position.y = -0.4;

  const tl = gsap.timeline();
  tl.to(content.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.to(material, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0);
  tl.to(
    content.scale,
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.45, ease: 'power2.out' },
    0.7
  );
  tl.to(
    content.scale,
    { x: 1, y: 1, z: 1, duration: 0.45, ease: 'power4.out' },
    1.15
  );

  const idleTween = gsap.to(content.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 4,
    ease: 'sine.inOut',
    repeat: -1,
    yoyo: true,
    delay: 1.6,
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    idleTween.kill();
    geometry.dispose();
    material.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    placeholderTex.dispose();
    if (texNode.value && texNode.value !== placeholderTex) {
      // texture is loader-cached elsewhere; do not dispose shared resource
    }
    content.remove(rimLight);
    content.clear();
    root.clear();
  };

  return root;
}
